//! Request input: `RequestParams` (untrusted, all strings) → `validate()` → `NewRequest` (typed).
//! Generated by `cargo offrails generate resource requests agent:references{agent} title:string description:text category:string location:string budget:money`.

use serde::Deserialize;

use super::Model;
use crate::models::Errors;

/// Untrusted input from the request form. This struct IS the permit list: no owner. All strings, so a
/// failed submit re-renders exactly what was typed.
#[derive(Debug, Default, Clone, Deserialize)]
pub struct RequestParams {
    #[serde(default)]
    pub agent_id: String,
    #[serde(default)]
    pub title: String,
    #[serde(default)]
    pub description: String,
    #[serde(default)]
    pub category: String,
    #[serde(default)]
    pub location: String,
    #[serde(default)]
    pub budget: String,
}

/// Validated, typed values. Only `RequestParams::validate` makes one.
#[derive(Debug, Clone, PartialEq)]
pub struct NewRequest {
    pub agent_id: i64,
    pub title: String,
    pub description: String,
    pub category: String,
    pub location: String,
    pub budget_cents: i64,
}

impl RequestParams {
    /// Rails wording: "can't be blank", "is too long (maximum is N characters)".
    pub fn validate(&self) -> Result<NewRequest, Errors> {
        let mut errors = Errors::default();
        let agent_id = match self.agent_id.trim() {
            "" => {
                errors.add("agent", "must exist");
                0
            }
            raw => match raw.parse::<i64>().ok().filter(|id| *id > 0) {
                Some(v) => v,
                None => {
                    errors.add("agent", "must exist");
                    0
                }
            },
        };
        let title = self.title.trim();
        if title.is_empty() {
            errors.add("title", "can't be blank");
        } else if title.chars().count() > 255 {
            errors.add("title", "is too long (maximum is 255 characters)");
        }
        let description = self.description.trim();
        if description.is_empty() {
            errors.add("description", "can't be blank");
        } else if description.chars().count() > 100000 {
            errors.add("description", "is too long (maximum is 100000 characters)");
        }
        let category = self.category.trim();
        if category.is_empty() {
            errors.add("category", "can't be blank");
        } else if category.chars().count() > 255 {
            errors.add("category", "is too long (maximum is 255 characters)");
        }
        let location = self.location.trim();
        if location.is_empty() {
            errors.add("location", "can't be blank");
        } else if location.chars().count() > 255 {
            errors.add("location", "is too long (maximum is 255 characters)");
        }
        let budget_cents = match self.budget.trim() {
            "" => {
                errors.add("budget", "can't be blank");
                0
            }
            raw => match parse_money(raw) {
                Some(v) => v,
                None => {
                    errors.add("budget", "is not an amount");
                    0
                }
            },
        };
        if budget_cents < 0 {
            errors.add("budget", "must be zero or greater");
        }
        if !category.is_empty() && !super::CATEGORIES.iter().any(|(key, _)| *key == category) {
            errors.add("category", "must be one of the listed categories");
        }
        errors.into_result(|| NewRequest {
            agent_id,
            title: title.to_owned(),
            description: description.to_owned(),
            category: category.to_owned(),
            location: location.to_owned(),
            budget_cents,
        })
    }
}

/// Prefills the edit form.
impl From<&Model> for RequestParams {
    fn from(r: &Model) -> Self {
        Self {
            agent_id: r.agent_id.to_string(),
            title: r.title.clone(),
            description: r.description.clone(),
            category: r.category.clone(),
            location: r.location.clone(),
            budget: money_to_string(r.budget_cents),
        }
    }
}

/// `"12.30"` → `1230` cents; at most two decimals, an optional `-`. `None`: not an amount.
pub fn parse_money(raw: &str) -> Option<i64> {
    let raw = raw.trim().replace(',', "");
    let (negative, digits) = match raw.strip_prefix('-') {
        Some(rest) => (true, rest.to_owned()),
        None => (false, raw),
    };
    let (whole, frac) = digits.split_once('.').unwrap_or((&digits, ""));
    let ok = |s: &str| s.chars().all(|c| c.is_ascii_digit());
    if whole.is_empty() && frac.is_empty() || !ok(whole) || !ok(frac) || frac.len() > 2 {
        return None;
    }
    let whole: i64 = if whole.is_empty() {
        0
    } else {
        whole.parse().ok()?
    };
    let frac: i64 = format!("{frac:0<2}").parse().ok()?;
    let cents = whole.checked_mul(100)?.checked_add(frac)?;
    Some(if negative { -cents } else { cents })
}

/// `1230` cents → `"12.30"`.
pub fn money_to_string(cents: i64) -> String {
    let sign = if cents < 0 { "-" } else { "" };
    let abs = cents.unsigned_abs();
    format!("{sign}{}.{:02}", abs / 100, abs % 100)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn valid() -> RequestParams {
        RequestParams {
            agent_id: "1".into(),
            title: "Title".into(),
            description: "Description text".into(),
            category: "research".into(),
            location: "Location".into(),
            budget: "19.99".into(),
        }
    }

    #[test]
    fn valid_params_validate() {
        assert!(valid().validate().is_ok(), "{:?}", valid().validate());
    }

    #[test]
    fn required_fields_cant_be_blank() {
        let errors = RequestParams::default().validate().unwrap_err();
        assert_eq!(errors.on("agent"), ["must exist"]);
        assert_eq!(errors.on("title"), ["can't be blank"]);
        assert_eq!(errors.on("description"), ["can't be blank"]);
        assert_eq!(errors.on("category"), ["can't be blank"]);
        assert_eq!(errors.on("location"), ["can't be blank"]);
        assert_eq!(errors.on("budget"), ["can't be blank"]);
    }

    #[test]
    fn strings_have_a_maximum_length() {
        let at_max = RequestParams {
            title: "x".repeat(255),
            ..valid()
        };
        assert!(at_max.validate().is_ok());
        let over = RequestParams {
            title: "x".repeat(256),
            ..valid()
        };
        assert_eq!(
            over.validate().unwrap_err().on("title"),
            ["is too long (maximum is 255 characters)"]
        );
        let at_max = RequestParams {
            description: "x".repeat(100000),
            ..valid()
        };
        assert!(at_max.validate().is_ok());
        let over = RequestParams {
            description: "x".repeat(100001),
            ..valid()
        };
        assert_eq!(
            over.validate().unwrap_err().on("description"),
            ["is too long (maximum is 100000 characters)"]
        );
        let at_max = RequestParams {
            category: "x".repeat(255),
            ..valid()
        };
        assert!(
            at_max
                .validate()
                .unwrap_err()
                .on("category")
                .iter()
                .all(|e| !e.contains("too long"))
        );
        let over = RequestParams {
            category: "x".repeat(256),
            ..valid()
        };
        assert_eq!(
            over.validate().unwrap_err().on("category"),
            [
                "is too long (maximum is 255 characters)",
                "must be one of the listed categories"
            ]
        );
        let at_max = RequestParams {
            location: "x".repeat(255),
            ..valid()
        };
        assert!(at_max.validate().is_ok());
        let over = RequestParams {
            location: "x".repeat(256),
            ..valid()
        };
        assert_eq!(
            over.validate().unwrap_err().on("location"),
            ["is too long (maximum is 255 characters)"]
        );
    }

    #[test]
    fn typed_fields_reject_garbage() {
        let bad = RequestParams {
            agent_id: "abc".into(),
            ..valid()
        };
        assert_eq!(bad.validate().unwrap_err().on("agent"), ["must exist"]);
        let bad = RequestParams {
            budget: "12.345".into(),
            ..valid()
        };
        assert_eq!(
            bad.validate().unwrap_err().on("budget"),
            ["is not an amount"]
        );
    }

    #[test]
    fn money_round_trips_as_cents() {
        assert_eq!(parse_money("12"), Some(1200));
        assert_eq!(parse_money("12.3"), Some(1230));
        assert_eq!(parse_money("-0.05"), Some(-5));
        assert_eq!(parse_money("1.234"), None);
        assert_eq!(parse_money("abc"), None);
        assert_eq!(money_to_string(1230), "12.30");
        assert_eq!(money_to_string(-5), "-0.05");
    }
}
